/*
 * Video API setup. You normally do NOT edit this file.
 * Easiest way to connect an API: edit the "vars" in worker/wrangler.jsonc
 *   - Known provider:   "API_PRESET": "pexels"   (or "pixabay")  +  wrangler secret put VIDEO_API_KEY
 *   - Any other API:    "API_BASE_URL": "https://api.example.com/v1", "API_LIST_PATH": "videos"  +  the secret
 * Everything else (where the video list is, title / thumbnail / video / views / tags fields, paging,
 * categories) is detected automatically. Use the optional API_* vars only if auto-detect picks the wrong thing.
 */

/* Ready-made providers. */
export const PRESETS = {
  pexels: {
    provider: "pexels",
    baseUrl: "https://api.pexels.com/",
    listPath: "videos/popular",
    searchPath: "videos/search",
    itemsPath: "videos",
    pageParameter: "page",
    limitParameter: "per_page",
    searchParameter: "query",
    categoryAsSearch: true,          // Pexels has no category API: a category is searched as a keyword
    authMode: "header", authHeader: "Authorization", authPrefix: "",
    topics: ["Nature", "City", "People", "Technology", "Animals", "Travel", "Food", "Sports", "Business", "Abstract", "Ocean", "Space"],
    map(v) {
      const files = (v.video_files || []).filter(f => f.file_type === "video/mp4" && f.link);
      const best = files.filter(f => (f.width || 0) <= 1280).sort((a, b) => (b.width || 0) - (a.width || 0))[0] || files[0];
      const slug = String(v.url || "").split("/").filter(Boolean).pop() || "";
      const title = slug.replace(/-\d+$/, "").replace(/-/g, " ").trim();
      return {
        title: title ? title.charAt(0).toUpperCase() + title.slice(1) : "Pexels video",
        thumbnail: v.image, playback: best && best.link, source: v.url,
        channel: v.user && v.user.name, durationSeconds: v.duration
      };
    }
  },
  /* Adult video API with /video/search/, /categories/, /oembed/ ... (no key needed). 18+ only: the site shows an age gate. */
  eporner: {
    provider: "eporner",
    baseUrl: "https://www.eporner.com/api/v2/",
    listPath: "video/search/",
    searchPath: "video/search/",
    categoriesPath: "categories/",
    itemsPath: "videos",
    pageParameter: "page",
    limitParameter: "per_page",
    searchParameter: "query",
    defaultQuery: "all",                       // this API requires a query; "all" lists everything
    extraParams: { thumbsize: "big", format: "json", lq: "0" },
    categoryAsSearch: true,                    // a category is searched as a keyword
    sortParameter: "order", sortPopular: "most-popular", sortNewest: "latest",
    authMode: "none",
    map(v) {
      const tags = String(v.keywords || "").split(",").map(t => t.trim()).filter(Boolean);
      const t = v.default_thumb || (v.thumbs && v.thumbs[0]) || {};
      const embed = v.embed && /^https?:/i.test(v.embed) ? v.embed
        : (v.embed && (String(v.embed).match(/src=["']([^"']+)/) || [])[1]) || (v.id ? "https://www.eporner.com/embed/" + v.id + "/" : "");
      return {
        title: v.title, thumbnail: t.src, playback: embed, source: v.url,
        views: v.views, durationSeconds: v.length_sec, published: v.added, categories: tags.slice(0, 4)
      };
    }
  },
  pixabay: {
    provider: "pixabay",
    baseUrl: "https://pixabay.com/api/",
    listPath: "videos/",
    searchPath: "videos/",
    itemsPath: "hits",
    pageParameter: "page",
    limitParameter: "per_page",
    searchParameter: "q",
    categoryParameter: "category",    // Pixabay has real categories (below); the slug is sent as-is
    sortParameter: "order", sortPopular: "popular", sortNewest: "latest",
    authMode: "query", authQueryParameter: "key",
    topics: ["Backgrounds", "Fashion", "Nature", "Science", "Education", "Feelings", "Health", "People", "Places", "Animals", "Industry", "Computer", "Food", "Sports", "Transportation", "Travel", "Buildings", "Business", "Music"],
    map(v) {
      const vv = v.videos || {}, pick = vv.medium || vv.small || vv.large || vv.tiny || {};
      const tags = String(v.tags || "").split(",").map(t => t.trim()).filter(Boolean);
      return {
        title: tags.length ? tags.slice(0, 4).join(", ").replace(/^./, c => c.toUpperCase()) : "Pixabay video",
        thumbnail: pick.thumbnail, playback: pick.url, source: v.pageURL,
        channel: v.user, durationSeconds: v.duration, views: v.views, categories: tags.slice(0, 3)
      };
    }
  }
};

/* Generic defaults for any other API. Empty = auto-detect. */
export const DEFAULTS = {
  provider: "video-api",
  baseUrl: "", listPath: "", searchPath: "", categoriesPath: "",
  itemsPath: "", categoriesItemsPath: "",
  pageParameter: "page", limitParameter: "limit", searchParameter: "q", categoryParameter: "category",
  sortParameter: "", sortPopular: "popular", sortNewest: "newest",
  categoryAsSearch: false, defaultQuery: "", extraParams: {},
  authMode: "header",                       // header | query | none
  authHeader: "Authorization", authPrefix: "Bearer ", authQueryParameter: "api_key",
  fields: {},                               // optional overrides, e.g. { title: "snippet.title" }
  embedUrlTemplate: "",                     // e.g. https://player.example.com/{id}
  topics: [], cacheSeconds: 60, syncPageSize: 50
};

/* Other names APIs commonly use. The first one that exists wins. */
export const ALIASES = {
  id: ["id", "uuid", "video_id", "videoId", "_id", "guid", "slug"],
  title: ["title", "name", "headline", "caption"],
  description: ["description", "summary", "desc", "excerpt"],
  thumbnail: ["thumbnail_url", "thumbnailUrl", "thumbnail", "thumb", "thumbnails.high", "thumbnails.medium", "image", "image_url", "poster", "poster_url", "cover", "preview_image", "picture"],
  playback: ["embed_url", "embedUrl", "player_url", "playback_url", "playbackUrl", "video_url", "videoUrl", "stream_url", "mp4_url", "file", "src", "url", "link"],
  source: ["source_url", "page_url", "web_url", "share_url", "permalink", "url", "link"],
  channel: ["channel.title", "channel.name", "channel_title", "channelTitle", "author.name", "author", "user.name", "user.username", "user", "uploader", "owner.name", "creator"],
  published: ["published_at", "publishedAt", "created_at", "createdAt", "uploaded_at", "release_date", "date", "created"],
  durationSeconds: ["duration_seconds", "durationSeconds", "duration", "length", "runtime"],
  views: ["view_count", "viewCount", "views", "play_count", "plays", "statistics.viewCount"],
  categories: ["categories", "category", "genres", "genre", "topics", "tags"],
  categoryName: ["name", "title", "label", "slug"],
  categoryId: ["id", "slug", "key"]
};
